  const roll = Math.floor(nextUnit(world) * 0xffffffff) >>> 0;
  const base = Number(world?.seed || 0) >>> 0;
  const step = Number(world?.step || 0) >>> 0;
  return (base ^ roll ^ ((step * 0x9e3779b9) >>> 0) ^ 0x52494654) >>> 0;
}

