    if (next.length === 0) return { x: curX, y: curY, steps };
    if (next.length > 1) return null;
    if (steps >= 2) return null;

    prevX = curX; prevY = curY;
    curX = next[0][0]; curY = next[0][1];
    steps++;
  }
}

